-- 20261019120000 added hygiene sets and sleep anchors (End/Start Sleep) to every catalogue Protocol.
-- They belong only to hygiene/beauty routines (hygiene) and sleep/wellness routines (sleep); elsewhere
-- the website shows them as suggested daily basics instead. Remove exactly the rows that migration
-- inserted (its explicit ids), and only from protocols with a known, off-theme category: an unknown
-- (blank) category keeps its basics, as routineStandard.standardiseProtocol does.
DELETE FROM public.protocol_items i
USING public.protocols p
WHERE p.id = i.protocol_id
  AND p.user_id IS NULL
  AND nullif(btrim(p.category), '') IS NOT NULL
  AND i.id = ANY (ARRAY[
